(function (window, $) {

    // 确保 wp 对象存在
    window.wp = window.wp || {};

    // 建立 mediaelement 模块
    window.wp.mediaelement = new function () {

        var settings = {};

        return {

            initialize: function () {

                var selectors = [];

                // 读取 WordPress 设置（如果有）
                settings = (typeof _wpmejsSettings !== "undefined")
                    ? $.extend(true, {}, _wpmejsSettings)
                    : settings;

                // 设置 CSS class 前缀
                settings.classPrefix = "mejs-";

                // 播放成功时的处理（主要给旧 Flash 用）
                settings.success = settings.success || function (media) {

                    if (media.rendererName &&
                        media.rendererName.indexOf("flash") !== -1) {

                        var autoplay = media.attributes.autoplay !== "false";
                        var loop = media.attributes.loop !== "false";

                        // 自动播放
                        if (autoplay) {
                            media.addEventListener("canplay", function () {
                                media.play();
                            }, false);
                        }

                        // 循环播放
                        if (loop) {
                            media.addEventListener("ended", function () {
                                media.play();
                            }, false);
                        }
                    }
                };

                // 错误处理：提供下载链接
                settings.customError = function (media, node) {

                    if (media.rendererName &&
                        (media.rendererName.indexOf("flash") !== -1 ||
                         media.rendererName.indexOf("flv") !== -1)) {

                        return '<a href="' + node.src + '">' +
                               mejsL10n.strings["mejs.download-file"] +
                               '</a>';
                    }
                };

                // 选择需要处理的元素
                if (settings.videoShortcodeLibrary === undefined ||
                    settings.videoShortcodeLibrary === "mediaelement") {
                    selectors.push(".wp-video-shortcode");
                }

                if (settings.audioShortcodeLibrary === undefined ||
                    settings.audioShortcodeLibrary === "mediaelement") {
                    selectors.push(".wp-audio-shortcode");
                }

                // 初始化播放器
                if (selectors.length) {
                    $(selectors.join(", "))
                        .not(".mejs-container")
                        .filter(function () {
                            return !$(this).parent().hasClass("mejs-mediaelement");
                        })
                        .mediaelementplayer(settings);
                }
            }
        };
    };

    // 页面加载时执行
    $(window.wp.mediaelement.initialize);

})(window, jQuery);